import java.util.*;
import java.io.*;

public class HeightAllTheSame {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        long N = sc.nextLong();
        long M = sc.nextLong();
        long L = sc.nextLong();
        long R = sc.nextLong();
        long totalCells = N * M;
        long rangeSize = R - L + 1;
        long result;
        if (totalCells % 2 != 0) {
            result = powerMod(rangeSize, totalCells, 998244353);
        } else if (rangeSize % 2 == 0) {
            result = (powerMod(rangeSize, totalCells, 998244353) * (998244353 + 1) / 2) % 998244353;
        } else {
            result = ((powerMod(rangeSize, totalCells, 998244353) + 1) * (998244353 + 1) / 2) % 998244353;
        }
        System.out.println(result);
        sc.close();
    }

    static long powerMod(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }
}
